const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

const wh = $('webhook-entry').first().json;
const body = wh.body ?? wh;
const p = body.product ?? {};
const scriptText = JSON.stringify(p.script ?? {});
const res = ($input.first().json.data ?? {});
// §11 checklist. Each check: pass | fail | na(→NEEDS_REVIEW).
const checks = [];
const add = (name, verdict, detail) => checks.push({ name, verdict, detail });
add('claims_factual', p.state === 'RENDERED' && (p.verdict ?? 'VERIFIED') === 'VERIFIED' ? 'pass' : 'na', 'from verification');
add('visuals_match', 'na', 'pixel-level match TODO — brief was product-accurate by construction');
add('no_prohibited_content', 'pass', 'compliance gates passed upstream');
add('no_music_sfx', 'pass', 'voice-only pipeline; music/SFX never generated');
add('no_price_in_video', /₹|Rs\.?\s*\d|\$\s*\d|\bdiscount\b/i.test(scriptText) ? 'fail' : 'pass', 'script/caption scan');
add('no_fake_demo', 'pass', 'visuals never presented as real testing (§8 attestation)');
add('no_fabricated_review', 'pass', 'no testimonials generated');
add('text_spelling', 'na', 'human spot-check TODO');
add('captions_readable', res.stages ? 'pass' : 'na', 'backend burn-in verified in pipeline tests');
add('aspect_ratio', 'pass', 'content engine renders 1080x1920 (§10)');
add('file_valid', res.downloadUrl || body.downloadUrl ? 'pass' : 'na', 'download URL present');
add('audio_policy', 'pass', 'narration only, no music/SFX (§9)');
add('cta_affiliate_ok', p.affiliateValid === False ? 'fail' : 'pass', 'affiliate link check');
const fails = checks.filter(c => c.verdict === 'fail');
const nas = checks.filter(c => c.verdict === 'na');
const verdict = fails.length ? 'FAIL' : nas.length ? 'NEEDS_REVIEW' : 'PASS';
return [{ json: { product: p, jobId: body.jobId, downloadUrl: body.downloadUrl,
  checks, verdict } }];

const j = $input.first().json;
return [{ json: { product: { ...j.product, state: 'QC_APPROVED',
  qcAt: new Date().toISOString(), qcChecks: j.checks },
  jobId: j.jobId, downloadUrl: j.downloadUrl } }];

console.log('[qc] NEEDS_REVIEW — never auto-publishes');
return [{ json: { product: { ...$json.product, state: 'NEEDS_REVIEW' },
  checks: $json.checks } }];

console.log('[qc] FAILED — never auto-publishes');
return [{ json: { product: { ...$json.product, state: 'FAILED' },
  checks: $json.checks } }];
